#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include "h3api.h"
#include "h3Index.h"
int main(){
 long vals[] = {-2147483648LL,-2147483647LL,-2000000000LL,-1073741824LL,-1000000000LL,-1000000,-1000,-10,-3,-2,-1,0,1,2,3,10,1000,1000000,1000000000LL,1073741824LL,2000000000LL,2147483646LL,2147483647LL};
 int bcs[]={0,4,14,24,38,49,58,63,72,83,97,107,117};
 for(int res=0;res<=15;res++) for(int bi=0;bi<13;bi++) {
  H3Index h=H3_INIT; H3_SET_MODE(h,H3_CELL_MODE); H3_SET_RESOLUTION(h,res); H3_SET_BASE_CELL(h,bcs[bi]);
  for(int di=0; di<8; di++) { H3Index h2=h; for(int r=1;r<=res;r++) H3_SET_INDEX_DIGIT(h2,r,di);
   for(unsigned a=0;a<sizeof(vals)/sizeof(vals[0]);a++) for(unsigned b=0;b<sizeof(vals)/sizeof(vals[0]);b++){
    CoordIJ ij={(int)vals[a],(int)vals[b]}; H3Index out;
    printf("try res=%d bc=%d d=%d i=%d j=%d h=%llx\n",res,bcs[bi],di,ij.i,ij.j,(unsigned long long)h2); fflush(stdout);
    H3_EXPORT(localIjToCell)(h2,&ij,0,&out);
   }
  }
 }
}
EOF
